// 原型内容按 Workbench 现有组件排布；repoSnapshot 是生成时的只读快照。
document.querySelectorAll('[data-icon]').forEach(el => { el.innerHTML = icon(el.dataset.icon) });
const main = document.getElementById('main'), side = document.getElementById('sidebar');
const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const label = {backlog:'待批准',todo:'待认领',in_progress:'进行中',in_review:'待验收',blocked:'受阻',done:'已完成',canceled:'已取消'};
const views = {全部:[],工作中:['in_progress'],待我决定:['in_review','blocked'],待办:['backlog','todo'],已完成:['done']};
const nav = {
 overview:{name:'概览',items:['空间概览','目标与进展','团队场景']},
 agents:{name:'Agent',items:[]},
 tasks:{name:'任务',items:['全部','工作中','待我决定','待办','已完成','日程日历']},
 resources:{name:'资源',items:['文件中心','技能中心','规范']},
 activity:{name:'动态',items:['通知中心','实时动态','上下文快照']},
 settings:{name:'设置',items:['空间管理','持续执行','Agent 工作流','模型与凭证','连接与令牌','浏览器助手']}
};
let page='agents', sub='', scope=repoSnapshot.spaces.find(s=>s.id==='software')?.id || repoSnapshot.spaces[0]?.id || '', selectedAgent=null, selectedTask=null, search='', roleFilter='', taskQuery='', chatTab='对话', drawerOpen=false, timer;
const drafts={}, localMessages={}, collapsed=new Set();
const allAgents = repoSnapshot.roster.map((a,i)=>({...a,id:`${a.scope}:${a.role}`,color:['purple','teal','blue','orange'][i%4],initial:a.name.slice(0,1)}));
selectedAgent=allAgents.find(a=>a.scope===scope && a.role==='coder')?.id || allAgents[0]?.id;
const spaceName = id => repoSnapshot.spaces.find(s=>s.id===id)?.name || id;
const agentTasks = a => repoSnapshot.tasks.filter(t=>t.scope===a.scope && (t.soldier===a.role || (!t.soldier&&t.role===a.role)));
const scopedTasks = () => repoSnapshot.tasks.filter(t=>!scope||t.scope===scope);
const agentMode = a => {const ts=agentTasks(a);return ts.some(t=>t.status==='blocked')?'受阻':ts.some(t=>t.status==='in_review')?'待验收':ts.some(t=>t.status==='in_progress')?'工作中':'空闲'};
const avatar = a => `<div class="avatar ${a.color}">${escapeHTML(a.initial)}</div>`;
const btn = (name,action,primary=false) => `<button class="${primary?'primary':'filter'}" data-action="${escapeHTML(action||name)}">${escapeHTML(name)}</button>`;
function notify(text){const t=document.getElementById('toast');t.textContent=text;t.hidden=false;clearTimeout(timer);timer=setTimeout(()=>t.hidden=true,3500)}
function previewAction(name){notify(`${name}：展示现有功能入口，原型不会写入仓库或调用服务`)}
function preserve(){const input=document.getElementById('message-input');if(input&&selectedAgent)drafts[selectedAgent]=input.value}
function sourceFooter(){return `<div class="side-foot"><strong>Legion 协作台</strong><span style="margin-left:auto">仓库快照</span></div>`}
function spacePicker(){return `<select id="space-picker" class="filter" aria-label="选择工作空间" style="width:100%"><option value="">全部空间</option>${repoSnapshot.spaces.map(s=>`<option value="${escapeHTML(s.id)}" ${scope===s.id?'selected':''}>${escapeHTML(s.name)}</option>`).join('')}</select>`}
function renderSide(){
 side.innerHTML=`<div class="side-head"><span class="side-title">${nav[page].name}</span>${page==='agents'?`<button class="icon-btn" aria-label="管理工作空间" data-action="空间管理">${icon('settings')}</button>`:''}</div><div style="padding:0 18px 16px">${spacePicker()}</div>${page==='agents'?`<div class="search-wrap" style="margin-bottom:15px">${icon('search')}<input class="search" id="agent-search" placeholder="搜索名称、岗位或空间" aria-label="搜索 Agent" value="${escapeHTML(search)}"></div><div class="side-scroll" id="directory"></div>`:`<div class="side-scroll"><div class="nav-section-title">${page==='tasks'?'任务视角':'工作区'}</div>${nav[page].items.map(n=>`<button class="nav-row ${sub===n?'active':''}" data-sub="${n}">${n}${page==='tasks'&&views[n]?`<small>${scopedTasks().filter(t=>t.status!=='canceled'&&(!views[n].length||views[n].includes(t.status))).length}</small>`:''}</button>`).join('')}${page==='tasks'?`<div class="nav-section-title">任务操作</div>${['发布目标','任务调度','新建任务','导出日报'].map(n=>`<button class="nav-row" data-action="${n}">${n}</button>`).join('')}`:''}</div>`}${sourceFooter()}`;
 document.getElementById('space-picker').onchange=e=>{preserve();scope=e.target.value;roleFilter='';render()};
 if(page==='agents'){renderDirectory();document.getElementById('agent-search').oninput=e=>{search=e.target.value;renderDirectory()}}
 side.querySelectorAll('[data-sub]').forEach(b=>b.onclick=()=>{sub=b.dataset.sub;render()});bindActions(side);
}
function renderDirectory(){const target=document.getElementById('directory');target.innerHTML=repoSnapshot.spaces.filter(s=>!scope||s.id===scope).map(s=>{
 const list=allAgents.filter(a=>a.scope===s.id && `${a.name}${a.role}${s.name}`.toLowerCase().includes(search.toLowerCase()));
 if(search&&!list.length)return '';
 return `<section class="group"><button class="group-toggle" data-group="${escapeHTML(s.id)}" aria-expanded="${!collapsed.has(s.id)}"><span class="chevron">⌄</span>${escapeHTML(s.name)}<span class="group-count">${list.length}</span></button><div ${collapsed.has(s.id)?'hidden':''}>${list.map(a=>{const ts=agentTasks(a),active=ts.filter(t=>!['done','canceled'].includes(t.status));return `<button class="agent ${a.id===selectedAgent?'active':''}" data-agent="${escapeHTML(a.id)}" ${a.id===selectedAgent?'aria-current="true"':''}>${avatar(a)}<div class="agent-info"><div class="agent-name">${escapeHTML(a.name)}</div><div class="agent-sub ${agentMode(a)==='受阻'?'attention':''}">${agentMode(a)} · ${active.length} 个活动任务</div></div></button>`}).join('')}${!list.length?'<div class="agent-sub" style="padding:12px">该空间尚无编队成员</div>':''}<button class="discussion" data-space-chat="${escapeHTML(s.id)}">${icon('chat')}空间会话</button></div></section>`}).join('')||'<div class="agent-sub" style="padding:15px">没有匹配的 Agent</div>';
 target.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{collapsed.has(b.dataset.group)?collapsed.delete(b.dataset.group):collapsed.add(b.dataset.group);renderDirectory()});
 target.querySelectorAll('[data-agent]').forEach(b=>b.onclick=()=>selectAgent(b.dataset.agent));
 target.querySelectorAll('[data-space-chat]').forEach(b=>b.onclick=()=>renderSpaceChat(b.dataset.spaceChat));
}
function selectAgent(id){preserve();selectedAgent=id;page='agents';sub='';chatTab='对话';drawerOpen=false;render();side.classList.remove('open')}
function header(title,subtitle,actions=''){return `<header class="header"><div class="header-identity"><button class="icon-btn mobile-menu" data-mobile aria-label="打开导航">${icon('menu')}</button><div><div class="header-name">${escapeHTML(title)}</div><div class="header-sub">${escapeHTML(subtitle)}</div></div></div><div class="header-actions">${actions}</div></header>`}
function snapshotNote(){return `<div class="repo-note">只读设计预览 · ${escapeHTML(repoSnapshot.capturedAt)} 仓库快照 · 不表示当前运行状态</div>`}
function renderAgent(){const a=allAgents.find(x=>x.id===selectedAgent);if(!a){main.innerHTML=header('Agent','按空间查看编队成员')+'<div class="board-page">选择一个空间中的 Agent。</div>';return}
 const ts=agentTasks(a),done=ts.filter(t=>t.status==='done').length;
 main.innerHTML=header(a.name,`${spaceName(a.scope)} · ${a.role} · ${agentMode(a)} · 已完成 ${done}/${ts.filter(t=>t.status!=='canceled').length}`,`<button class="quiet-btn" id="context-toggle">${icon('panel')}任务清单 ${ts.length}</button><button class="icon-btn" aria-label="默认模型" data-action="快速分配">${icon('settings')}</button>`)+`<div class="agent-tabs">${['对话','任务'].map(n=>`<button data-chat-tab="${n}" class="${chatTab===n?'selected':''}">${n}</button>`).join('')}<span>Agent 对话为本次新增设计</span></div><div class="main-row"><section class="chat-pane">${chatTab==='对话'?`<div class="chat-body" id="chat-body"><div class="chat-content"><div class="welcome" style="margin-top:35px"><div style="display:flex;justify-content:center;margin-bottom:14px">${avatar(a)}</div><strong style="font-size:17px">${escapeHTML(a.name)}</strong><p>${escapeHTML(a.kind)}</p><div style="font-size:11px;max-width:410px;margin:18px auto">已按仓库岗位展示任务上下文。现有空间会话保留在左侧；此处预览按 Agent 进入聊天的新布局。</div></div><div class="task-card" style="max-width:520px;margin:0 auto 30px"><div class="task-card-head">${icon('list')}仓库任务摘要<span class="task-status">${agentMode(a)}</span></div><div class="task-card-main"><div class="task-title">${ts.filter(t=>!['done','canceled'].includes(t.status)).length} 个活动任务 · ${done} 个已完成</div>${ts.slice(0,3).map(t=>`<button class="task-link" data-task="${escapeHTML(t.id)}"><span>${escapeHTML(t.id)} · ${escapeHTML(t.title)}</span><small>${label[t.status]}</small></button>`).join('')||'<div class="progress-line">当前岗位没有任务记录</div>'}</div></div><div id="messages">${(localMessages[a.id]||[]).map(m=>renderLocalMessage(m)).join('')}</div></div></div><div class="composer-area"><div class="composer"><textarea id="message-input" aria-label="发消息给 ${escapeHTML(a.name)}" placeholder="发消息给 ${escapeHTML(a.name)}…"></textarea><div class="composer-controls"><button class="icon-btn" id="attach" aria-label="选择附件">${icon('clip')}</button><input type="file" id="file-input" hidden><span id="attachment-label" class="agent-sub"></span><div class="composer-right"><span class="hint">Enter 发送 · Shift + Enter 换行</span><button class="send" id="send">发送 ${icon('send')}</button></div></div></div><div class="footer-label"><span>聊天交互演示 · 未连接 Agent 回复服务</span><span>${escapeHTML(a.scope)} / ${escapeHTML(a.role)}</span></div></div>`:`<div class="board-page"><div class="page-title-row"><div><h1>任务清单</h1><p>沿用 AgentTasksModal 的任务分组</p></div>${btn('默认模型','快速分配')}</div>${['活动任务','已完成','已取消'].map((name,i)=>{const list=ts.filter(t=>i===0?!['done','canceled'].includes(t.status):t.status===(i===1?'done':'canceled'));return `<section class="generic-list"><h3>${name} · ${list.length}</h3>${list.map(taskRow).join('')||'<small class="agent-sub">暂无任务</small>'}</section>`}).join('')}</div>`}</section><aside class="drawer" id="drawer" hidden><div style="display:flex;justify-content:space-between"><strong>关联任务</strong><button class="icon-btn" id="drawer-close" aria-label="关闭任务抽屉">${icon('close')}</button></div><h4>${escapeHTML(a.name)} · ${escapeHTML(spaceName(a.scope))}</h4>${ts.slice(0,12).map(taskRow).join('')||'<div class="agent-sub">暂无任务</div>'}<h4>岗位模型</h4><div class="agent-sub">默认模型通过“模型与凭证 → 快速分配”设置。</div></aside></div>`;
 main.querySelectorAll('[data-chat-tab]').forEach(b=>b.onclick=()=>{preserve();chatTab=b.dataset.chatTab;renderAgent()});document.getElementById('context-toggle').onclick=()=>{drawerOpen=!drawerOpen;document.getElementById('drawer').hidden=!drawerOpen};document.getElementById('drawer-close').onclick=()=>{drawerOpen=false;document.getElementById('drawer').hidden=true};
 const input=document.getElementById('message-input');if(input){input.value=drafts[a.id]||'';input.oninput=()=>drafts[a.id]=input.value;input.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();sendMessage()}};document.getElementById('send').onclick=sendMessage;document.getElementById('attach').onclick=()=>document.getElementById('file-input').click();document.getElementById('file-input').onchange=e=>{document.getElementById('attachment-label').textContent=e.target.files[0]?.name||'';notify('附件仅在本地显示，不会上传')}}bindContent();
}
function renderLocalMessage(m){return `<div class="message user"><div class="avatar blue">我</div><div class="msg-wrap"><div class="msg-meta">我 · 本地演示</div><div class="bubble">${escapeHTML(m).replace(/\n/g,'<br>')}</div><div class="receipt">已添加到原型 · 未发送</div></div></div>`}
function sendMessage(){const input=document.getElementById('message-input');if(!input.value.trim())return;localMessages[selectedAgent]??=[];localMessages[selectedAgent].push(input.value.trim());document.getElementById('messages').insertAdjacentHTML('beforeend',renderLocalMessage(input.value.trim()));input.value='';drafts[selectedAgent]='';const sc=document.getElementById('chat-body');sc.scrollTop=sc.scrollHeight;notify('仅添加演示消息，未调用 Agent，也未写入空间会话')}
function renderSpaceChat(id){preserve();const list=repoSnapshot.conversations.filter(c=>c.scope===id);main.innerHTML=header('空间会话',`${spaceName(id)} · 现有 ChatView 入口`,btn('新建会话'))+`<div class="board-page"><div class="generic-list"><h3>已有会话</h3>${list.map(c=>`<div class="generic-item"><div>${escapeHTML(c.title)}<div class="agent-sub">${escapeHTML(c.kind)} · 会话 #${c.id}</div></div>${btn('查看会话')}</div>`).join('')||'<div class="agent-sub">快照中没有该空间的会话记录</div>'}</div><div class="generic-list"><h3>会话功能</h3><p class="agent-sub">新建会话、加载更早、附件、引用回复、回复失败重试、AI 回复设置。</p>${['AI 回复设置','回复健康状态'].map(n=>btn(n)).join(' ')}</div>${snapshotNote()}</div>`;bindContent()}
function taskRow(t){return `<div class="generic-item"><button class="task-link" data-task="${escapeHTML(t.id)}" style="flex:1;margin:0;padding:0"><span>${escapeHTML(t.id)} · ${escapeHTML(t.title)}</span></button><small style="white-space:nowrap">${label[t.status]}</small></div>`}
function renderTasks(){if(sub==='日程日历'){renderCalendar();return}const ts=scopedTasks();const statuses=views[sub]||[];const filtered=ts.filter(t=>t.status!=='canceled'&&(!statuses.length||statuses.includes(t.status))&&(!roleFilter||(t.soldier||t.role)===roleFilter)&&`${t.id}${t.title}`.toLowerCase().includes(taskQuery.toLowerCase()));main.innerHTML=header('任务中心',`${scope?spaceName(scope):'全部空间'} · Scrum 泳道`,`${btn('发布目标')}${btn('任务调度')}${btn('新建任务','新建任务',true)}`)+`<div class="board-page"><div class="toolbar"><div class="view-pills">${Object.keys(views).map(n=>`<button class="filter ${sub===n?'on':''}" data-view="${n}">${n} ${ts.filter(t=>t.status!=='canceled'&&(!views[n].length||views[n].includes(t.status))).length}</button>`).join('')}</div><input class="search" style="max-width:220px;padding-left:12px" id="task-search" aria-label="搜索任务 id 或标题" placeholder="搜索任务 id / 标题…" value="${escapeHTML(taskQuery)}"></div><div class="toolbar"><div class="view-pills"><span class="agent-sub">岗位 / 执行者</span><select class="filter" id="role-picker" aria-label="岗位或执行者"><option value="">全部岗位</option>${[...new Set(ts.map(t=>t.soldier||t.role).filter(Boolean))].map(r=>`<option ${r===roleFilter?'selected':''}>${escapeHTML(r)}</option>`).join('')}</select></div><span class="agent-sub">待验收 ${ts.filter(t=>t.status==='in_review').length} · 受阻 ${ts.filter(t=>t.status==='blocked').length} · 已取消 ${ts.filter(t=>t.status==='canceled').length}</span></div><div class="columns repo-columns">${Object.entries(label).filter(([s])=>s!=='canceled').map(([s,n],i)=>{const list=filtered.filter(t=>t.status===s);return `<section class="column"><div class="column-heading"><span class="tiny-dot" style="background:${['#a2aaba','#90a2b8','#008594','#d7a053','#c88674','#70a58c'][i]}"></span>${n}<span class="number">${list.length}</span></div>${list.slice(0,12).map(taskCard).join('')||'<div class="agent-sub" style="padding:12px 4px">暂无符合条件的任务</div>'}${list.length>12?`<div class="agent-sub">另有 ${list.length-12} 项，原型仅展示前 12 项</div>`:''}</section>`}).join('')}</div>${snapshotNote()}</div>`;
main.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{sub=b.dataset.view;render()});document.getElementById('role-picker').onchange=e=>{roleFilter=e.target.value;renderTasks()};document.getElementById('task-search').oninput=e=>{const pos=e.target.selectionStart;taskQuery=e.target.value;renderTasks();const el=document.getElementById('task-search');el.focus();el.setSelectionRange(pos,pos)};bindContent()}
function taskCard(t){return `<button class="board-card" data-task="${escapeHTML(t.id)}"><span class="project-pill">${escapeHTML(t.id)}</span><div class="card-title">${escapeHTML(t.title)}</div>${t.hold?'<span class="task-status" style="background:#f7ede3;color:#ac8156">已拦截</span>':''}<div class="card-meta"><span class="priority" style="background:${t.priority==='high'?'#dc8d6e':'#a5adb9'}"></span>${escapeHTML(t.priority)}<span>${escapeHTML(t.soldier||t.role||'未指派')}</span></div><div class="agent-sub" style="margin-top:9px">${escapeHTML(t.goalId||'独立任务')} · v${t.version}</div></button>`}
function openTask(id){selectedTask=repoSnapshot.tasks.find(t=>t.id===id);if(!selectedTask)return;const t=selectedTask;const controls={backlog:['认领','开工'],todo:['认领','开工'],in_progress:['提交验收','归还待办'],in_review:['验收通过','打回重做'],blocked:['解阻'],done:[],canceled:[]}[t.status]||[];const a=allAgents.find(a=>a.scope===t.scope&&a.role===(t.soldier||t.role));let modal=document.getElementById('detail-modal');if(modal)modal.remove();modal=document.createElement('div');modal.id='detail-modal';modal.className='detail-mask';modal.innerHTML=`<section class="detail-dialog" role="dialog" aria-modal="true" aria-label="${escapeHTML(t.id)} 任务详情"><div class="detail-head"><strong>${escapeHTML(t.id)} · 任务详情</strong><button class="icon-btn" id="detail-close" aria-label="关闭任务详情">${icon('close')}</button></div><div class="detail-body"><span class="task-status">${label[t.status]}</span><h2>${escapeHTML(t.title)}</h2><p class="agent-sub">空间 ${escapeHTML(t.scope)} · 指派 ${escapeHTML(t.soldier||t.role||'未指派')} · 优先级 ${escapeHTML(t.priority)} · v${t.version}</p><div class="agent-sub">目标 ${escapeHTML(t.goalId||'—')} · 依赖 ${escapeHTML((t.blockedBy||[]).join('、')||'无')}</div><div class="detail-section"><h3>任务描述</h3><p>${escapeHTML(t.description||'暂无描述').replace(/\n/g,'<br>')}</p></div><div class="detail-section"><h3>验收标准</h3>${(t.acceptance||[]).map(x=>`<p>□ ${escapeHTML(typeof x==='string'?x:JSON.stringify(x))}</p>`).join('')||'<p class="agent-sub">未定义验收标准，以任务描述与目标要求判断</p>'}</div><div class="detail-section"><h3>Agent 工作流与实际运行记录</h3><p class="agent-sub">现有详情包含阶段 Attempt、停止请求、人工核对及文件占用。原型未导出运行记录，不能由任务状态推断运行成功。</p></div><div class="detail-section"><h3>AI 执行过程 · 审计与交付</h3><div class="view-pills">${['过程记录','改动与 diff','测试报告','文档产物','评论与反馈','交付状态'].map(n=>btn(n)).join('')}</div><p class="agent-sub">沿用 TaskDetailModal 中的执行、证据、补丁、文档阅读和验收入口。</p></div></div><div class="detail-foot">${controls.map(n=>btn(n)).join('')}${btn('派 AI 执行')}${btn(t.hold?'放行自动交接':'拦截自动交接')}${btn('转派')}${a?`<button class="primary" id="detail-contact">联系 ${escapeHTML(a.name)}</button>`:''}</div></section>`;document.body.appendChild(modal);document.getElementById('detail-close').onclick=()=>modal.remove();modal.onclick=e=>{if(e.target===modal)modal.remove()};if(a)document.getElementById('detail-contact').onclick=()=>{modal.remove();scope=a.scope;selectAgent(a.id)};bindActions(modal);document.getElementById('detail-close').focus()}
function section(title,content){return `<section class="generic-list"><h3>${title}</h3>${content}</section>`}
function item(title,meta,action){return `<div class="generic-item"><div>${escapeHTML(title)}<div class="agent-sub">${escapeHTML(meta)}</div></div>${action?btn(action):''}</div>`}
function renderOverview(){const ts=scopedTasks(),goals=repoSnapshot.goals.filter(g=>!scope||g.scope===scope);main.innerHTML=header(sub,scope?spaceName(scope):'全部空间',`${btn('发布目标','发布目标',true)}${btn('导出日报')}`)+`<div class="board-page">${sub==='团队场景'?section('Agent 团队 · 3D 场景入口',`<p class="agent-sub">办公室、创作室、实验室、运营中心四种场景预设；保留现有 Scene3D，原型以岗位列表表示。</p>${allAgents.filter(a=>!scope||a.scope===scope).map(a=>`<div class="generic-item"><div>${escapeHTML(a.name)}<div class="agent-sub">${escapeHTML(a.kind)} · ${agentMode(a)}</div></div><button class="text-btn" data-agent="${escapeHTML(a.id)}">进入聊天 ↗</button></div>`).join('')}`):`<div class="generic-grid">${[['进行中 / 待验收',ts.filter(t=>['in_progress','in_review'].includes(t.status)).length],['已完成',ts.filter(t=>t.status==='done').length],['编队成员',allAgents.filter(a=>!scope||a.scope===scope).length]].map(([n,count])=>`<div class="summary-card"><small>${n}</small><strong>${count}</strong></div>`).join('')}</div>${section('空间目标',goals.slice(0,8).map(g=>{const gt=repoSnapshot.tasks.filter(t=>t.goalId===g.id&&t.status!=='canceled');const d=gt.filter(t=>t.status==='done').length;return `<div class="generic-item"><div style="flex:1"><span class="project-pill">${escapeHTML(g.id)} · ${escapeHTML(g.status)}</span><div style="margin-top:8px">${escapeHTML(g.objective)}</div><div class="agent-sub">${d}/${gt.length} 已完成 · 上下文 v${g.contextVersion} · 目标 v${g.version}</div></div><div class="view-pills">${['共享上下文','暂停 / 恢复','取消目标'].map(n=>btn(n)).join('')}</div></div>`}).join('')||'<p class="agent-sub">没有目标记录</p>')}`}${snapshotNote()}</div>`;bindContent()}
function renderResources(){let content='';if(sub==='文件中心')content=`<div class="toolbar"><div class="agent-sub">空间仓库 / ${escapeHTML(scope||'全部空间')}</div><div class="view-pills">${['上级','新建目录','上传','刷新'].map(n=>btn(n)).join('')}</div></div><div class="search-wrap" style="margin:0 0 20px"><input class="search" placeholder="在当前目录按文件名搜索…" aria-label="按文件名搜索"></div>${section('仓库目录',repoSnapshot.files.map(f=>item(f.name,f.type==='dir'?'目录':'文件',f.type==='dir'?'打开':'预览')).join(''))}${section('文件操作',`<div class="view-pills">${['下载文件','移动到…','批量删除','重命名','差异'].map(n=>btn(n)).join('')}</div><p class="agent-sub">搜索支持当前目录与递归搜索；文本预览、Git 差异及批量操作保留。</p>`)}`;
if(sub==='技能中心')content=`<div class="toolbar"><span class="agent-sub">本空间技能与跨空间共享</span><div class="view-pills">${btn('安装技能')}${btn('注册新技能','注册新技能',true)}</div></div>${section('团队技能源仓库',`<div class="view-pills"><input class="filter" placeholder="GitHub 技能源仓库地址" aria-label="技能源仓库地址">${btn('拉取同步')}</div><p class="agent-sub">冲突策略：升级（版本 +1 待审）或跳过。</p>`)}${section('技能目录',repoSnapshot.skills.filter(s=>!scope||s.scope===scope||s.status==='published').slice(0,10).map(s=>item(s.name,`${s.scope} · ${s.status==='published'?'已发布':s.status==='pending'?'待复审':'已驳回'} · v${s.version}`,'编辑 / 授权')).join('')||'<p class="agent-sub">快照中没有可展示的技能。</p>')}${section('技能管理',`<div class="view-pills">${['发布','驳回','授权空间 / Agent','撤销授权'].map(n=>btn(n)).join('')}</div>`)}`;
if(sub==='规范')content=section('全局规范层',`<textarea class="repo-textarea" aria-label="全局规范" placeholder="跨空间统一规范，最多 3000 字" maxlength="3000"></textarea><div class="view-pills" style="justify-content:flex-end">${btn('还原')}${btn('保存全局规范','保存全局规范',true)}</div>`)+section('空间层规范载体',`${['LEGION.md','AGENTS.md','agent.md'].map(n=>item(n,'空间绑定仓库中的规范文件','打开文件中心')).join('')}<p class="agent-sub">空间 / 项目层文件族优先于全局层；在绑定仓库中维护。</p>`);
main.innerHTML=header(sub,scope?spaceName(scope):'全部空间')+`<div class="board-page">${content}${snapshotNote()}</div>`;bindContent()}
function renderActivity(){let content='';if(sub==='通知中心')content=`<div class="toolbar"><div class="view-pills">${['全部','任务','目标','空间','模型','技能'].map(n=>btn(n,'分类：'+n)).join('')}</div>${btn('全部已读')}</div>${section('通知',`<label class="agent-sub"><input type="checkbox"> 仅看未读</label> ${btn('标记选中已读')}<p class="agent-sub">通知从既有审计动作派生；快照未导出用户已读状态，原型不展示虚构未读数。</p>${scopedTasks().filter(t=>['blocked','in_review'].includes(t.status)).slice(0,6).map(t=>`<div class="generic-item"><div>${escapeHTML(t.id)} · ${label[t.status]}<div class="agent-sub">${escapeHTML(t.title)}</div></div><button class="text-btn" data-task="${escapeHTML(t.id)}">打开任务 ↗</button></div>`).join('')}`)}`;
if(sub==='实时动态')content=section('任务与空间活动',`<p class="agent-sub">现有 ActivityFeed 展示任务发布、认领、开工、评论、提交、验收等事件。原型未导出审计事件，不把任务更新时间伪装成事件时间线。</p>${btn('刷新')}`);
if(sub==='上下文快照')content=section('执行上下文',`<div class="toolbar"><input class="filter" placeholder="按 attemptId / runId 过滤" aria-label="快照过滤">${btn('刷新')}</div><div class="repo-table-head"><span>Attempt / Run</span><span>版本与来源</span><span>操作</span></div><p class="agent-sub">快照列表未载入。实际页面支持查看正文、来源账本、被排除来源、脱敏位置、已清理记录与导出这一份。</p>${btn('导出这一份')}`);
main.innerHTML=header(sub,scope?spaceName(scope):'全部空间')+`<div class="board-page">${content}${snapshotNote()}</div>`;bindContent()}
function renderSettings(){const s=repoSnapshot.spaces.find(x=>x.id===scope);let content='';if(sub==='空间管理')content=section('工作空间',repoSnapshot.spaces.map(s=>item(s.name,`${s.id} · ${s.private?'本地 / 私有':'共享'} · ${allAgents.filter(a=>a.scope===s.id).length} 个岗位`,'空间设置')).join(''))+section('空间设置',`<div class="repo-form"><label>空间 id<input value="${escapeHTML(s?.id||'') }" readonly></label><label>空间名称<input value="${escapeHTML(s?.name||'')}"></label><label>3D 办公室场景<select><option>办公室</option><option>创作室</option><option>实验室</option><option>运营中心</option></select></label><label>本地文件夹<input value="${s?.id==='software'?'D:/project/DSH/legion':''}" placeholder="绑定空间工作目录"></label><label>远程仓库 URL<input placeholder="可选，仅本地使用时留空"></label></div><p class="agent-sub">另含本地 / 私有空间设置、删除空间的确认流程。</p>${btn('新建空间')}`);
if(sub==='持续执行')content=section('持续执行编排',`<p class="agent-sub">对具体空间开启自动派工；分析阶段自动执行，写码阶段可从任务详情派 AI 执行。</p><label class="repo-switch"><input type="checkbox" id="exec-demo"> 持续执行编排（本地演示开关）</label><p class="agent-sub">守护在线状态未载入，不能由配置文件的历史心跳确认当前在线。</p>`)+section('全局调度',`${btn('全部暂停')}${btn('全部继续')}<p class="agent-sub">控制守护后续认领 / 派工，不等价于停止所有正在运行的 Agent。</p>`);
if(sub==='Agent 工作流')content=section('空间阶段与工作流',`<p class="agent-sub">复用 AgentWorkflowConfigurator，管理岗位阶段、工作流定义与执行实例。</p><div class="pipeline">${repoSnapshot.stages.filter(x=>!scope||x.scope===scope).map(s=>`<div><strong>${escapeHTML(s.label)}</strong><small>${escapeHTML(s.role)} · ${s.enabled?'启用':'停用'}</small></div>`).join('')}</div>`)+section('执行配置',`<div class="view-pills">${['Agent 工具配置','节点注册','工作流定义','执行实例与历史'].map(n=>btn(n)).join('')}</div><p class="agent-sub">工具选择：DSH Native、Claude Code、Codex。每阶段保留工具 / 模型配置引用、节点、输入输出产物及测试配置。</p>`);
if(sub==='模型与凭证')content=`<div class="view-pills model-tabs">${['快速分配','模型档案','岗位绑定','配置搬家','凭证库'].map(n=>`<button class="filter ${n==='快速分配'?'on':''}" data-model-tab="${n}">${n}</button>`).join('')}</div><div id="model-content">${modelContent('快速分配')}</div>`;
if(sub==='连接与令牌')content=section('数据连接',`<div class="repo-form"><label>Workbench 数据源<input placeholder="serve.mjs 地址"></label><label>team-hub 地址<input placeholder="team-hub 服务地址"></label><label>写操作令牌<input type="password" autocomplete="off" placeholder="设置写操作令牌"></label></div><p class="agent-sub">保留 KpiBar 现有数据源、中枢地址与令牌设置入口。</p>${btn('保存连接')}`);
if(sub==='浏览器助手')content=section('页面抓取与历史',`<div class="toolbar"><input class="filter" placeholder="输入页面 URL" aria-label="页面 URL" style="flex:1">${btn('抓取页面','抓取页面',true)}</div><p class="agent-sub">复用 BrowserView 的 URL 抓取和 web_fetch_history，不把浏览器助手降为只读说明。</p>${btn('查看抓取历史')}`);
main.innerHTML=header(sub,scope?spaceName(scope):'请先选择具体空间')+`<div class="board-page">${content}${snapshotNote()}</div>`;main.querySelectorAll('[data-model-tab]').forEach(b=>b.onclick=()=>{main.querySelectorAll('[data-model-tab]').forEach(x=>x.classList.toggle('on',x===b));document.getElementById('model-content').innerHTML=modelContent(b.dataset.modelTab);bindActions(document.getElementById('model-content'))});bindContent()}
function modelContent(tab){const bodies={快速分配:allAgents.filter(a=>!scope||a.scope===scope).map(a=>item(a.name,`${a.role} · 岗位默认模型`,'选择模型')).join(''),模型档案:`<div class="view-pills">${['新建档案','编辑档案','测试连接'].map(n=>btn(n)).join('')}</div><p class="agent-sub">档案配置不等于模型连接已验证。</p>`,岗位绑定:`<p class="agent-sub">每空间岗位绑定模型档案，保留 fallback 设置。</p>${btn('编辑绑定')}`,配置搬家:`<div class="view-pills">${['导入配置','导出配置'].map(n=>btn(n)).join('')}</div>`,凭证库:`<p class="agent-sub">凭证独立管理，不在配置导出或此原型中嵌入真实密钥。</p>${btn('管理凭证')}`};return section(tab,bodies[tab])}
function renderCalendar(){main.innerHTML=header('日程日历',`${scope?spaceName(scope):'全部空间'} · 独立日程条目`,btn('新建条目','新建条目',true))+`<div class="board-page"><div class="toolbar"><div class="view-pills">${['上一月','今天','下一月'].map(n=>btn(n)).join('')}</div><span>2026 年 10 月</span><div class="view-pills">${btn('月')}${btn('周')}</div></div><div class="calendar-grid">${['一','二','三','四','五','六','日'].map(n=>`<div class="calendar-week">${n}</div>`).join('')}${Array.from({length:35},(_,i)=>{const d=i-2;return `<div class="calendar-day ${d===2?'today':''}">${d>0&&d<=31?d:''}</div>`}).join('')}</div><p class="agent-sub">保留全天 / 起止时间、每日 / 每周 / 每月重复、结束日期 / 次数、任务号与目标号；不将日程伪装成任务截止日期。</p>${snapshotNote()}</div>`;bindContent()}
function bindActions(root){root.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{const n=b.dataset.action;if(['空间管理','快速分配'].includes(n)){preserve();page='settings';sub=n==='空间管理'?n:'模型与凭证';render()}else if(n==='打开文件中心'){page='resources';sub='文件中心';render()}else previewAction(n)})}
function bindContent(){bindActions(main);main.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>openTask(b.dataset.task));main.querySelectorAll('[data-agent]').forEach(b=>b.onclick=()=>selectAgent(b.dataset.agent));main.querySelectorAll('[data-mobile]').forEach(b=>b.onclick=()=>side.classList.toggle('open'))}
function render(){if(!sub&&nav[page].items.length)sub=nav[page].items[0];document.querySelectorAll('[data-page]').forEach(b=>{const on=b.dataset.page===page;b.classList.toggle('active',on);if(on)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});renderSide();if(page==='agents')renderAgent();if(page==='tasks')renderTasks();if(page==='overview')renderOverview();if(page==='resources')renderResources();if(page==='activity')renderActivity();if(page==='settings')renderSettings()}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{preserve();page=b.dataset.page;sub='';roleFilter='';drawerOpen=false;side.classList.remove('open');render()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.getElementById('detail-modal')?.remove();const d=document.getElementById('drawer');if(d)d.hidden=true;side.classList.remove('open')}});
render();
